    agregar("G-09-50-11", CLASE_50, "L2", "Al acelerar a fondo en subida se escucho un chasquido sordo y el EV entro en modo tortuga. La bateria de traccion marca 70% de carga pero no entrega torque a las ruedas.", "TECNICO", "SUBIDA_FUERTE", "modo_tortuga, chasquido, sin_torque", "bateria_descargada", "", "NO", "SI", CLASE_49, "L2 contraste con paquete de bateria HV")
    agregar("G-09-50-12", CLASE_50, "L2", "En plena autopista sono una detonacion leve bajo el capot frontal y el auto electrico perdio propulsion de golpe, tablero indica fallo de sistema motriz con luz READY parpadeando.", "COLOQUIAL", "CARRETERA", "detonacion_leve, perdida_propulsion, ready_parpadea", "falla_mecanica_frenos", "", "NO", "NO", "", "L2 fallo subito de etapa inversora")
