    agregar("G-09-50-25", CLASE_50, "L2", "Hibrido enchufable no conmuta a modo EV puro; al forzarlo arroja advertencia de fallo en motor electrico de propulsion, manteniendo funcionamiento exclusivo a gasolina.", "TECNICO", "CAMBIO_MODO_EV", "modo_ev_inhabilitado, falla_motor_electrico", "falla_motor_gasolina", "", "NO", "NO", "", "L2 imposibilidad modo electrico puro")

