    agregar("G-09-50-33", CLASE_50, "L3", "El vehiculo electrico presenta bloqueo motriz; medicion en bus DC de entrada a inversor marca 395V estables desde bateria HV, pero tension eficaz AC de salida en bornes de motor es 0V RMS al comandar acelerador, confirmando destruccion de etapa inversora.", "TECNICO", "TALLER_MEDICION", "bus_dc_395v_ok, salida_ac_0v_rms, inversor_destruido", "bateria_hv_descargada", "", "NO", "SI", CLASE_49, "L3 tension bus DC vs salida AC inversor")
