    agregar("G-09-51-11", CLASE_51, "L2", "En vehiculo hibrido con refrigeracion por aire en paquete de bateria NiMH, la turbina de enfriamiento trasera funciona a maxima velocidad constante y el tablero advierte reduccion de potencia tras circular 20 minutos en calor.", "TECNICO", "MARCHA_URBANA_CALOR", "turbina_maxima_velocidad, reduccion_potencia_hibrido", "degradacion_celdas_quimica", "", "NO", "SI", CLASE_49, "L2 refrigeracion aire vs fallo celdas")
    agregar("G-09-51-12", CLASE_51, "L2", "Al circular por autopista en dia caluroso el vehiculo electrico reduce potencia a la mitad; el deposito de refrigerante del circuito del inversor no muestra turbulencia ni flujo circulante.", "TECNICO", "CARRETERA_CALOR", "deposito_sin_flujo, reduccion_potencia", "dano_igbt_inversor", "", "NO", "SI", CLASE_50, "L2 falta de flujo refrigerante vs fallo IGBT")
    agregar("G-09-51-13", CLASE_51, "L2", "Aparece testigo de falla en sistema hibrido con codigo P0A93 en escaner; el circuito de enfriamiento del inversor no mueve liquido y el deposito auxiliar se calienta en exceso.", "TECNICO", "MARCHA_URBANA", "dtc_p0a93, sin_flujo_refrigerante_inversor", "falla_motor_combustion", "P0A93", "NO", "NO", "", "L2 DTC P0A93 bomba inversor")
    agregar("G-09-51-14", CLASE_51, "L2", "La rejilla de toma de aire del ventilador de bateria de traccion bajo el asiento trasero estaba tapada con polvo y pelos de mascota; el ventilador vibra atorado y salta alerta termica.", "COLOQUIAL", "EN_MARCHA", "rejilla_tapada_polvo, ventilador_atorado, alerta_termica", "dano_modulo_bateria", "", "NO", "SI", CLASE_49, "L2 obstruccion aire vs dano quimico")
    agregar("G-09-51-15", CLASE_51, "L2", "En subidas prolongadas el inversor se sobrecalienta y enciende foco de temperatura; la bomba electrica de refrigerante de la unidad de control de potencia no se activa.", "TECNICO", "SUBIDA_PROLONGADA", "sobrecalentamiento_inversor, bomba_electrica_inoperante", "falla_motor_traccion", "", "NO", "SI", CLASE_50, "L2 bomba inoperante vs fallo motor EV")
    agregar("G-09-51-16", CLASE_51, "L2", "El escaner arroja codigo P0A82 indicando problema de rendimiento en ventilador de enfriamiento 1 del paquete de bateria hibrida, operando de forma intermitente.", "TECNICO", "CONTACTO", "dtc_p0a82, ventilador_bateria_intermitente", "desbalance_de_celdas", "P0A82", "NO", "NO", "", "L2 DTC P0A82 ventilador paquete")
    agregar("G-09-51-17", CLASE_51, "L2", "Vehiculo 100% electrico cancela la recarga rapida en corriente continua DC a los 10 minutos debido a que el circuito chiller de refrigeracion liquida de bateria no logra abatir la temperatura.", "TECNICO", "CARGA_RAPIDA_DC", "carga_dc_cancelada, sobretemperatura_bateria, chiller_inoperante", "falla_estacion_carga", "", "NO", "SI", CLASE_49, "L2 enfriamiento carga DC vs estado bateria")
    agregar("G-09-51-18", CLASE_51, "L2", "El deposito de refrigerante rosado exclusivo del inversor de potencia esta vacio por fuga en abrazadera inferior; se enciende aviso de parada segura por alta temperatura de electronica.", "TECNICO", "DETENIDO_REVISION", "deposito_vacio_fuga, aviso_parada_segura", "falla_refrigerante_motor_termico", "", "NO", "NO", "", "L2 fuga de refrigerante de inversor")
    agregar("G-09-51-19", CLASE_51, "L2", "Durante el frenado regenerativo intenso en descenso de montana la temperatura del inversor se dispara a zona roja por falta de enfriamiento en el radiador auxiliar.", "TECNICO", "DESCENSO_MONTANA", "alta_temperatura_inversor, radiador_auxiliar_inoperante", "desgaste_pastillas_freno", "", "NO", "SI", CLASE_32, "L2 enfriamiento vs frenos regenerativos")
    agregar("G-09-51-20", CLASE_51, "L2", "El ventilador soplador centrifugo de la bateria de alto voltaje hace ruido de roce mecanico con sus aspas y no entrega caudal de aire suficiente hacia los modulos centrales.", "TECNICO", "EN_MARCHA", "roce_mecanico_aspas, bajo_caudal_aire", "falla_quimica_bateria", "", "NO", "NO", "", "L2 soplador centrifugo con roce")
    agregar("G-09-51-21", CLASE_51, "L2", "Se registra codigo P0A93 tras conducir 15 minutos en ciudad; el motor electrico y la transmision operan normalmente pero el inversor alcanza el limite termico por bomba trabada.", "TECNICO", "MARCHA_URBANA", "dtc_p0a93, limite_termico_inversor, bomba_trabada", "dano_igbt_interno", "P0A93", "NO", "SI", CLASE_50, "L2 P0A93 bomba trabada vs dano IGBT")
    agregar("G-09-51-22", CLASE_51, "L2", "El sistema termico del paquete de bateria de litio no activa la valvula de tres vias del circuito refrigerante, reteniendo calor en el nucleo central de celdas.", "TECNICO", "CARRETERA", "valvula_3_vias_trabada, retencion_calor_celdas", "falla_modulo_bms", "", "NO", "NO", "", "L2 electrovalvula termica de bateria")
    agregar("G-09-51-23", CLASE_51, "L2", "Auto hibrido desactiva el modo electrico y enciende testigo maestro; el sensor de temperatura en la entrada del ducto de aire de la bateria marca 48°C con flujo de aire bloqueado.", "TECNICO", "EN_MARCHA", "modo_electrico_desactivado, ducto_bloqueado, 48c", "bateria_agotada", "", "NO", "SI", CLASE_49, "L2 flujo aire bloqueado vs bateria agotada")
    agregar("G-09-51-24", CLASE_51, "L2", "Bomba electrica de agua de 12V dedicada al enfriamiento del inversor y convertidor boost emite chillido intermitente y se detiene repentinamente al calentarse.", "TECNICO", "RALENTI_CONTACTO", "chillido_bomba_inversor, detencion_termica", "bomba_agua_motor_termico", "", "NO", "NO", "", "L2 bomba 12V enfriamiento inversor")
    agregar("G-09-51-25", CLASE_51, "L2", "El paquete de bateria HV retiene 85% de capacidad util pero en dias calurosos el sistema recorta el paso de corriente debido a falta de disipacion en su circuito termico.", "TECNICO", "CALOR_AMBIENTE", "recorte_corriente_calor, disipacion_deficiente", "degradacion_soh_bateria", "", "NO", "SI", CLASE_49, "L2 disipacion deficiente vs degradacion SOH")

    # L3 (15 casos)
    agregar("G-09-51-26", CLASE_51, "L3", "Diagnostico de sistema termico en taller especializado: escaneo OBD arroja DTC P0A93 (Inverter Cooling System Performance). Con ignicion en ON, la bomba de refrigerante del inversor consume 0.0A por circuito abierto en inducido; temperatura de refrigerante de inversor alcanza 88°C con motor termico frio a 35°C.", "TECNICO", "TALLER_MEDICION", "dtc_p0a93, bomba_0_0a_abierta, temp_inversor_88c", "falla_termostato_motor_combustion", "P0A93", "NO", "SI", CLASE_50, "L3 bomba inversor abierta P0A93 temp 88C")
    agregar("G-09-51-27", CLASE_51, "L3", "Monitoreo de datos en vivo de BMS en vehiculo hibrido refrigerado por aire: termistores de modulo central marcan 56°C (umbral maximo seguro 45°C). Comando de activacion de ventilador al 100% de PWM desde escaner registra turbina girando a solo 620 RPM por obstruccion severa de pelusa en ducto de admision, generando DTC P0A82.", "TECNICO", "TALLER_SCANNER", "termistores_56c, ventilador_620rpm_obstruido, dtc_p0a82", "degradacion_irreversible_bateria", "P0A82", "NO", "SI", CLASE_49, "L3 termistores 56C ventilador 620RPM P0A82")
    agregar("G-09-51-28", CLASE_51, "L3", "Evaluacion de circuito de enfriamiento de inversor: comprobacion de flujo en deposito de expansion revela ausencia total de turbulencia. Medicion de alimentacion en conector de bomba electrica: 12.4V presentes y masa a chasis 0.02 Ohm; rotor de bomba trabado mecanicamente por impurezas en refrigerante OEM.", "TECNICO", "TALLER_COMPROBACION", "alimentacion_12_4v_ok, rotor_bomba_trabado, sin_turbulencia", "falla_cableado_alimentacion", "", "NO", "NO", "", "L3 bomba inversor trabada con 12.4V")
    agregar("G-09-51-29", CLASE_51, "L3", "Prueba de circuito termico de bateria de traccion en EV con refrigeracion liquida: sensor de temperatura de entrada de refrigerante registra 28°C y salida a 52°C. Caudalimetro de lazo termico mide 1.1 L/min frente al valor nominal de 8.5 L/min debido a bloqueo en electrovalvula proporcional de distribucion a celdas.", "TECNICO", "TALLER_MEDICION", "caudal_1_1_l_min_bloqueado, salto_termico_24c, electrovalvula_trabada", "falla_quimica_celdas", "", "NO", "SI", CLASE_49, "L3 caudal 1.1 L/min vs 8.5 nominal electrovalvula")
    agregar("G-09-51-30", CLASE_51, "L3", "Lectura de parametros en tiempo real durante prueba de ruta: la temperatura de semiconductores IGBT escala de 42°C a 115°C en 90 segundos al acelerar a 80 km/h; conector de retorno de refrigerante frio al tacto, confirmando aire entrampado o purga deficiente en circuito secundario con DTC P0A93.", "TECNICO", "PRUEBA_RUTA", "temperatura_igbt_115c_90s, aire_en_circuito, dtc_p0a93", "dano_modulo_igbt", "P0A93", "NO", "SI", CLASE_50, "L3 purga deficiente temp 115C P0A93")
    agregar("G-09-51-31", CLASE_51, "L3", "Inspeccion con camara termografica en bahia de bateria de alto voltaje: gradiente termico de 22°C entre modulos extremos (32°C) y centrales (54°C). El ducto de escape de aire forzado presenta compuerta de alivio trabada en posicion cerrada, impidiendo ventilacion convectiva.", "TECNICO", "TALLER_TERMOGRAFIA", "gradiente_termico_22c, compuerta_alivio_trabada, modulos_54c", "desbalance_interno_celdas", "", "NO", "SI", CLASE_49, "L3 termografia gradiente 22C compuerta cerrada")
    agregar("G-09-51-32", CLASE_51, "L3", "Auditoria electrica en conector de soplador de refrigeracion de bateria HV: senal de control PWM de 250 Hz presente con ciclo de trabajo de 85%, pero linea de retorno de tacometro (sensor Hall) permanece en 0 Hz; motor sin escobillas del soplador con bobinado de estator quemado, DTC P0A82.", "TECNICO", "TALLER_OSCILOSCOPIO", "pwm_85_ok, tacometro_0hz, estator_soplador_quemado, dtc_p0a82", "falla_controlador_bms", "P0A82", "NO", "NO", "", "L3 soplador PWM 85% tacometro 0Hz P0A82")
    agregar("G-09-51-33", CLASE_51, "L3", "Prueba de banco de bomba de refrigeracion de modulo de traccion electrica: al aplicar 12V directos la bomba consume corriente anormal de 6.8A (nominal 1.5A-2.2A) produciendo recalentamiento de devanado y disparo del fusible de proteccion de 15A tras 10 segundos de marcha.", "TECNICO", "TALLER_BANCO", "consumo_anormal_6_8a, fusible_15a_quemado, devanado_recalentado", "cortocircuito_en_arnes", "", "NO", "NO", "", "L3 sobreconsumo bomba inversor 6.8A")
    agregar("G-09-51-34", CLASE_51, "L3", "Evaluacion en estacion de carga rapida DC (50 kW): la sesion se interrumpe al llegar a 38% de SOC con codigo de error de sobretemperatura en paquete. Temperatura interna de pack medida por BMS a 58°C por falla en compresor electrico del circuito chiller de refrigeracion liquida.", "TECNICO", "ESTACION_CARGA", "interrupcion_38_soc, pack_58c, falla_compresor_chiller", "falla_quimica_pack", "", "NO", "SI", CLASE_49, "L3 corte carga rapida pack 58C chiller")
    agregar("G-09-51-35", CLASE_51, "L3", "Diagnostico con escaner automotriz en bus hibrido: DTC P0A93 confirmado en historial de fallas; parametros congelados registran temperatura de inversor a 108°C a 2100 RPM con radiador de inversor completamente frio por descebado de bomba y cavitacion en circuito cerrado.", "TECNICO", "TALLER_SCANNER", "dtc_p0a93, temp_108c_freeze_frame, cavitacion_bomba", "falla_propulsion_motor", "P0A93", "NO", "SI", CLASE_50, "L3 P0A93 cavitacion y radiador frio")
    agregar("G-09-51-36", CLASE_51, "L3", "Medicion con multimetro automotriz en sensor de temperatura de refrigerante de inversor (termistor NTC): resistencia medida a 20°C ambiente es 185 kiloohmios (valor fuera de rango segun manual OEM: 2.2 a 2.7 kiloohmios), enviando senal erronea de congelamiento e impidiendo arranque de bomba.", "TECNICO", "TALLER_MULTIMETRO", "sensor_ntc_185_kohm_descalibrado, lectura_falsa_frio", "falla_mecanica_bomba", "", "NO", "NO", "", "L3 sensor NTC inversor descalibrado 185k")
    agregar("G-09-51-37", CLASE_51, "L3", "Analisis de telemetria termica de pack de litio: la resistencia interna de las celdas esta pareja a 1.2 miliohmios (bateria en optimo estado quimico), pero ante demanda continua de 120A la temperatura sube sin disiparse a razon de 1.8°C/min por radiador de refrigeracion auxiliar obstruido con insectos.", "TECNICO", "PRUEBA_DINAMOMETRICA", "resistencia_1_2mohm_ok, subida_1_8c_min, radiador_auxiliar_tapado", "degradacion_celdas", "", "NO", "SI", CLASE_49, "L3 celdas 1.2 mOhm ok disipacion tapada")
    agregar("G-09-51-38", CLASE_51, "L3", "Verificacion de funcionamiento de electroventilador de radiador de inversor: actuador no responde a test bidireccional desde escaner. Rele de control RLY_INV_FAN con contactos carbonizados presenta caida de tension interna de 8.2V entre terminal 30 y 87.", "TECNICO", "TALLER_BIDIRECCIONAL", "test_bidireccional_falla, caida_8_2v_contactos_rele", "motor_ventilador_quemado", "", "NO", "NO", "", "L3 rele electroventilador con caida 8.2V")
    agregar("G-09-51-39", CLASE_51, "L3", "Prueba de hermeticidad y presion con manometro en circuito de refrigerante de alta tension: presion cae de 1.2 bar a 0.2 bar en 3 minutos. Se localiza fisura en manguera de retorno de placa disipadora del inversor de corriente, con acumulacion de liquido desionizado en bandeja inferior.", "TECNICO", "TALLER_PRESION", "perdida_presion_1_2_a_0_2bar, fisura_manguera_retorno", "fuga_aceite_transmision", "", "NO", "NO", "", "L3 prueba presion circuito desionizado")
    agregar("G-09-51-40", CLASE_51, "L3", "Control de soplador centrifugo de bateria NiMH: desmontaje de turbina revela 140 gramos de pelusa compactada entre los alabes; con canal despejado el consumo electrico del motor baja de 4.1A a 1.6A y la temperatura de celdas disminuye de 52°C a 34°C en 8 minutos de marcha urbana.", "TECNICO", "TALLER_MANTENIMIENTO", "pelusa_compactada_turbina, consumo_baja_4_1_a_1_6a, delta_temp_18c", "falla_pack_baterias", "", "NO", "SI", CLASE_49, "L3 mantenimiento turbina soplador NiMH")

