    # L2 (15 casos)
    agregar("G-09-52-11", CLASE_52, "L2", "Pongo contacto, las luces del tablero encienden con buen brillo, pero al girar la llave a start solo se escucha un clac metalico seco y el ciguenal no gira absolutamente nada.", "COLOQUIAL", "INTENTO_ARRANQUE", "clac_metalico_seco, luces_tablero_brillantes, no_crank", "luces_tenues, traqueteo_bateria", "", "NO", "SI", CLASE_48, "L2 no-crank con luces buenas vs bateria")
    agregar("G-09-52-12", CLASE_52, "L2", "El motor no gira en lo absoluto (no-crank); no es que gire rapido y no encienda como cuando falla el sensor de ciguenal CKP, aqui el motor de arranque esta completamente mudo.", "TECNICO", "INTENTO_ARRANQUE", "no_crank_absoluto, arrancador_mudo", "crank_normal_no_start", "", "NO", "SI", CLASE_21, "L2 NO-CRANK estricto vs CKP crank-no-start")
