    agregar("G-09-52-15", CLASE_52, "L2", "Falla intermitente en arranque en caliente: tras apagar el auto luego de viajar, le doy arranque y no gira; tras golpear suavemente el cuerpo del motor de arranque con una llave enciende al instante.", "COLOQUIAL", "ARRANQUE_CALIENTE", "no_gira_en_caliente, arranca_al_golpear_cuerpo", "falla_bomba_gasolina", "", "NO", "NO", "", "L2 carbones pegados arrancan con golpe")
    agregar("G-09-52-16", CLASE_52, "L2", "Al accionar la llave no hay traqueteo rapido de bateria descargada; se oye un unico 'tac' en el solenoide y el voltimetro del tablero apenas baja, motor completamente inmovil.", "TECNICO", "INTENTO_ARRANQUE", "tac_unico_solenoide, voltimetro_estable, no_crank", "traqueteo_ametralladora_reles", "", "NO", "SI", CLASE_48, "L2 tac unico sin traqueteo rapido vs 48")
    agregar("G-09-52-17", CLASE_52, "L2", "El auto se apago y ahora al dar marcha se escucha el rele bajo el volante pero el motor de arranque no emite ningun sonido, motor termico totalmente detenido sin girar.", "COLOQUIAL", "INTENTO_ARRANQUE", "rele_activa, arrancador_sin_sonido, sin_giro", "giro_normal_sin_encendido", "", "NO", "SI", CLASE_21, "L2 arrancador mudo vs falla CKP giro normal")
    agregar("G-09-52-18", CLASE_52, "L2", "Se conecta escaner y se observa codigo P0615 por circuito de rele de motor de arranque abierto; al puentear manualmente el conector el motor de arranque no reacciona.", "TECNICO", "TALLER_REVISION", "dtc_p0615, puente_sin_reaccion", "falla_sensor_ckp", "P0615", "NO", "NO", "", "L2 DTC P0615 circuito rele arranque")
    agregar("G-09-52-19", CLASE_52, "L2", "El vehiculo no da arranque por llave; la bateria es completamente nueva y el alternador cargaba a 14.1V antes de apagarlo, pero el arrancador quedo trabado sin girar.", "TECNICO", "INTENTO_ARRANQUE", "bateria_nueva, alternador_cargaba_14_1v, arrancador_trabado", "falla_carga_alternador", "", "NO", "SI", CLASE_47, "L2 alternador ok bateria ok vs 47")
    agregar("G-09-52-20", CLASE_52, "L2", "Girando la llave a posicion de marcha el tablero no se apaga ni titilan los testigos, pero el motor no gira ni medio milimetro; el solenoide no empuja la horquilla.", "COLOQUIAL", "INTENTO_ARRANQUE", "tablero_no_parpadea, sin_giro_motor, solenoide_no_desplaza", "luces_muertas", "", "NO", "SI", CLASE_48, "L2 tablero no colapsa vs bateria baja")
    agregar("G-09-52-21", CLASE_52, "L2", "El vehiculo quedo varado: el conductor intento encenderlo y tras un clic seco no hubo respuesta; se intento puente con cables pasa-corriente y el comportamiento fue exactamente identico, motor inmovil.", "COLOQUIAL", "INTENTO_ARRANQUE", "puente_con_cables_mismo_fallo, clic_seco, motor_inmovil", "arranca_con_cables", "", "NO", "SI", CLASE_48, "L2 cables auxilio no resuelven vs bateria")
    agregar("G-09-52-22", CLASE_52, "L2", "Al dar encendido el motor de arranque gira a altas revoluciones en vacio emitiendo un zumbido agudo continuo, sin acoplar el pinon a la corona del volante motor.", "TECNICO", "INTENTO_ARRANQUE", "arranque_gira_en_vacio, zumbido_agudo, sin_acople_corona", "motor_girando_con_compresion", "", "NO", "NO", "", "L2 bendix no engrana horquilla o resorte")
    agregar("G-09-52-23", CLASE_52, "L2", "Arranque intermitente en frio: hace cinco intentos con clac seco sin giro de ciguenal, y en el sexto intento gira con fuerza y arranca de inmediato, sintoma clasico de carbones en su limite.", "COLOQUIAL", "ARRANQUE_FRIO", "clac_sin_giro_5_veces, arranca_con_fuerza_despues", "bateria_agotandose", "", "NO", "NO", "", "L2 carbones en limite con contacto intermitente")
    agregar("G-09-52-24", CLASE_52, "L2", "Diferencia de sintoma clara: cuando fallo el sensor CKP el motor giraba alegremente pero no arrancaba; ahora al girar la llave hay silencio total en el vano motor, no-crank total.", "TECNICO", "INTENTO_ARRANQUE", "silencio_total, no_crank_total", "crank_normal_sin_chispa", "", "NO", "SI", CLASE_21, "L2 contraste explicito silencio vs CKP")
    agregar("G-09-52-25", CLASE_52, "L2", "En vehiculo con transmision manual, empujandolo en segunda velocidad arranca al instante con compresion normal, pero por llave el motor de arranque no gira.", "COLOQUIAL", "ARRANQUE_EMPUJE", "arranca_al_empujar, no_gira_por_llave", "falla_distribucion, falla_inyeccion", "", "NO", "NO", "", "L2 arranca empujado vs motor trabado")

    # L3 (15 casos)
    agregar("G-09-52-26", CLASE_52, "L3", "Diagnostico de condicion NO-CRANK en taller automotriz: bateria en reposo marca 12.65V. Al accionar llave a START, se miden 12.2V en borne de control Terminal 50 del solenoide, pero en borne de salida Terminal M hacia carbones hay 0.0V con caida de tension de 12.1V entre contactos principales del solenoide por pletina interna fogueada.", "TECNICO", "TALLER_VOLTIMETRO", "no_crank, terminal_50_12_2v, terminal_m_0v, caida_pletina_12_1v", "bateria_descargada", "", "NO", "SI", CLASE_48, "L3 caida de tension en pletina de solenoide")
    agregar("G-09-52-27", CLASE_52, "L3", "Prueba de caida de tension en circuito de arranque: entre poste positivo de bateria y borne Terminal 30 del arrancador se registra caida de solo 0.08V. Al dar arranque la bateria cae a 12.35V (sin consumo de corriente motriz) y la pinza amperimetrica marca 1.2A correspondientes unicamente a bobina de solenoide; carbones positivos gastados sin contacto en conmutador.", "TECNICO", "TALLER_AMPERIMETRO", "caida_borne_30_0_08v, consumo_1_2a_solo_solenoide, carbones_gastados", "consumo_arranque_200a", "", "NO", "NO", "", "L3 solo consumo de solenoide 1.2A carbones abiertos")
    agregar("G-09-52-28", CLASE_52, "L3", "Verificacion de condicion de no arranque mecanico: el ciguenal gira libremente con palanca de fuerza en perno de polea (sin traba mecanica de motor). Al girar llave a marcha, el inducido del motor de arranque no rota a pesar de recibir 12.4V en terminales 30 y 50; desmontaje confirma colector del inducido fogueado y resortes de carbones vencidos.", "TECNICO", "TALLER_MECANICO", "ciguenal_gira_manual_libre, terminal_30_y_50_12_4v, colector_fogueado", "motor_fundido_o_amarrado", "", "NO", "NO", "", "L3 descarte de traba mecanica de motor")
    agregar("G-09-52-29", CLASE_52, "L3", "Analisis de corriente con pinza amperimetrica osciloscopica en cable de alimentacion principal: pico de corriente transitoria al dar marcha es de 0 amperios mas alla de los 8A de activacion de bobina retenedora del automatico. Diagnostico confirma escobillas totalmente desgastadas con separacion fisica respecto a delgas.", "TECNICO", "TALLER_OSCILOSCOPIO", "corriente_motriz_0a, pulso_solenoide_8a, escobillas_separadas", "sobreconsumo_por_corto", "", "NO", "SI", CLASE_48, "L3 corriente motriz 0A con pinza osciloscopica")
    agregar("G-09-52-30", CLASE_52, "L3", "Diferenciacion tecnica estricta frente a falla de bateria: la bateria arroja 12.72V de circuito abierto y entrega 620 CCA en probador digital Midtronics (estado de salud 98%). Al conmutar contacto a arranque, la tension de bateria solo desciende a 12.40V con un unico chasquido metalico en el solenoide y 0 RPM de giro en ciguenal.", "TECNICO", "TALLER_MIDTRONICS", "bateria_12_72v_620cca_98soh, tension_cae_a_12_40v, chasquido_unico_0rpm", "bateria_en_mal_estado", "", "NO", "SI", CLASE_48, "L3 Midtronics 98% SOH descarte total bateria")
    agregar("G-09-52-31", CLASE_52, "L3", "Caso contrastivo frente a sensor CKP: con escaner conectado se verifica estado de arranque en datos en vivo: senal 'Starter Relay Command' activa en ON, pero RPM de motor permanece en 0 RPM fijas por inmovilidad fisica de arrancador. En falla de CKP el motor gira a 220-280 RPM por marcha pero no sincroniza inyeccion.", "TECNICO", "TALLER_SCANNER", "starter_relay_on, motor_0_rpm, inmovilidad_arrancador", "giro_250_rpm_sin_arranque", "", "NO", "SI", CLASE_21, "L3 0 RPM arranque vs 250 RPM giro en CKP")
    agregar("G-09-52-32", CLASE_52, "L3", "Prueba de alimentacion y masa en motor de arranque: caida de tension en linea de masa entre carcasa de arrancador y borne negativo de bateria es de 0.04V durante intento de encendido. Terminal 50 recibe 11.9V bajo carga pero el embolo del solenoide se traba mecanicamente a mitad de carrera sin empujar horquilla ni cerrar contactos.", "TECNICO", "TALLER_CAIDA_TENSION", "caida_masa_0_04v_ok, term50_11_9v, embolo_solenoide_trabado", "masa_deficiente", "", "NO", "NO", "", "L3 embolo trabado con masa perfecta 0.04V")
    agregar("G-09-52-33", CLASE_52, "L3", "Escaneo electronico y mediciones: DTC P0615 (Starter Relay Circuit) almacenado en BCM; prueba de continuidad en rele de arranque confirma circuito de control integro, pero medicion de resistencia en bobina de atraccion del solenoide marca infinito (circuito abierto por hilo fundido en borne de conexion).", "TECNICO", "TALLER_SCANNER", "dtc_p0615, bobina_atraccion_infinita_abierta", "falla_rele_bcm", "P0615", "NO", "NO", "", "L3 bobina atraccion abierta DTC P0615")
    agregar("G-09-52-34", CLASE_52, "L3", "Evaluacion en banco de pruebas de arrancador: al aplicar 12V directos con bateria de prueba de 700 CCA, el motor gira a 6500 RPM en vacio pero el pinon de ataque (bendix) patina sobre su embrague unidireccional de rodillos al aplicarle freno mecanico, impidiendo transferir par a la corona del volante.", "TECNICO", "TALLER_BANCO", "arrancador_6500rpm_vacio, bendix_patina_bajo_freno", "carbones_gastados", "", "NO", "NO", "", "L3 embrague unidireccional de bendix safado")
    agregar("G-09-52-35", CLASE_52, "L3", "Ensayo de rotor trabado en vehiculo: al girar la llave a start se escucha un 'clac' sordo y la tension de bateria se desploma bruscamente de 12.6V a 7.2V con corriente instantanea de 480A sin rotacion de ciguenal; bujes de bronce sinterizado del arrancador desalineados produciendo rozamiento y bloqueo mecanico de inducido contra piezas polares.", "TECNICO", "TALLER_MEDICION", "caida_a_7_2v, corriente_480a_rotor_trabado, bujes_desalineados", "bateria_agotada_en_vacio", "", "NO", "SI", CLASE_48, "L3 corriente 480A rotor trabado vs bateria seca")
    agregar("G-09-52-36", CLASE_52, "L3", "Diagnostico electrico: vehiculo con alternador operativo a 14.3V antes de falla; bateria con tension de reposo de 12.58V. Al conectar voltimetro entre borne Terminal 50 y masa de motor se comprueba llegada de 12.1V al accionar switch, pero conmutador de arranque presenta delgas del colector carbonizadas en sector de apoyo.", "TECNICO", "TALLER_VOLTIMETRO", "alternador_14_3v_ok, bateria_12_58v_ok, term50_12_1v, delgas_carbonizadas", "alternador_averiado", "", "NO", "SI", CLASE_47, "L3 alternador y bateria descartados conmutador sucio")
    agregar("G-09-52-37", CLASE_52, "L3", "Medicion con osciloscopio automotriz en linea de corriente de arranque: rampa de corriente muestra ausencia de ondulacion caracteristica de compresion de cilindros; consumo constante de solo 11A atribuible unicamente al solenoide sin conexion de la bobina de serie del motor de campo.", "TECNICO", "TALLER_OSCILOSCOPIO", "sin_ondulacion_compresion, consumo_constante_11a, motor_campo_abierto", "falla_compresion_cilindros", "", "NO", "NO", "", "L3 oscilograma plano de arranque 11A")
    agregar("G-09-52-38", CLASE_52, "L3", "Prueba en rampa de taller: con llave en contacto se realiza puente directo entre borne positivo directo (Terminal 30) y terminal de excitacion (Terminal 50) con cable de 4 mm2; solo salta chispa pequena de control sin ningun intento de giro del motor de arranque, confirmando falla interna de escobillas.", "TECNICO", "TALLER_PRUEBA_DIRECTA", "puente_term30_term50_sin_giro, chispa_control, escobillas_internas_danadas", "falla_switch_encendido", "", "NO", "NO", "", "L3 puente directo 30-50 sin giro")
    agregar("G-09-52-39", CLASE_52, "L3", "Desmontaje y metrologia de motor de arranque: medicion con calibrador pie de rey de longitud de carbones de arranque arroja 4.2 mm (limite de servicio OEM minimo 9.5 mm). Los cables flexibles trenzados hacen tope en la guia impidiendo que los resortes presionen el conmutador.", "TECNICO", "TALLER_METROLOGIA", "carbones_4_2mm_limite_9_5mm, tope_cables_trenzados", "desgaste_rotor", "", "NO", "NO", "", "L3 metrologia pie de rey carbones 4.2mm")
    agregar("G-09-52-40", CLASE_52, "L3", "Prueba de aislamiento y cortocircuito en bobinado de estator e inducido en inductor Growler: bobina de campo de cuatro polos presenta aislamiento superior a 10 Megaohmios a masa, pero inducido presenta cortocircuito entre delgas 14 y 15 por limaduras de cobre acumuladas en ranuras de mica.", "TECNICO", "TALLER_GROWLER", "inductor_growler_corto_delgas_14_15, aislamiento_campo_10mohm", "falla_solenoide", "", "NO", "NO", "", "L3 prueba inductiva en Growler corto inducido")

    # =========================================================================
    # CLASE 53: Fuga parasita de corriente en reposo (consumo nocturno de bateria) (40 casos: 10 L1, 15 L2, 15 L3)
    # =========================================================================
    # L1 (10 casos)
    agregar("G-09-53-01", CLASE_53, "L1", "Si dejo el carro parado dos dias amanece sin nada de bateria.", "COLOQUIAL", "ESTACIONADO_PROLONGADO", "descarga_dos_dias, bateria_vacia", "NO_REPORTA", "", "SI", "NO", "", "L1 descarga tras dos dias parado")
    agregar("G-09-53-02", CLASE_53, "L1", "Todas las mananas tengo que pedir puente para que prenda mi auto.", "COLOQUIAL", "ARRANQUE_MANANA", "requiere_puente_diario, no_prende_manana", "NO_REPORTA", "", "SI", "NO", "", "L1 requiere puente cada manana")
    agregar("G-09-53-03", CLASE_53, "L1", "La bateria se me muere sola durante la noche.", "COLOQUIAL", "REPOSO_NOCTURNO", "bateria_muere_noche", "NO_REPORTA", "", "SI", "NO", "", "L1 bateria se muere de noche")
    agregar("G-09-53-04", CLASE_53, "L1", "Compre bateria nueva la semana pasada y ya se volvio a descargar parada.", "COLOQUIAL", "ESTACIONADO", "bateria_nueva_descargada_parada", "NO_REPORTA", "", "SI", "NO", "", "L1 bateria nueva descargada parada")
    agregar("G-09-53-05", CLASE_53, "L1", "Si uso el carro a diario anda bien, pero el lunes despues del fin de semana no prende.", "COLOQUIAL", "FIN_DE_SEMANA", "falla_tras_fin_de_semana, diario_bien", "NO_REPORTA", "", "SI", "NO", "", "L1 falla fin de semana uso diario ok")
    agregar("G-09-53-06", CLASE_53, "L1", "Tengo un consumo que me agota la bateria con el motor apagado.", "COLOQUIAL", "MOTOR_APAGADO", "consumo_motor_apagado, bateria_agotada", "NO_REPORTA", "", "SI", "NO", "", "L1 consumo con motor apagado")
    agregar("G-09-53-07", CLASE_53, "L1", "El carro amanece totalmente muerto sin luces ni tablero.", "COLOQUIAL", "ARRANQUE_MANANA", "amanece_muerto, sin_luces_tablero", "NO_REPORTA", "", "SI", "NO", "", "L1 amanece totalmente muerto")
    agregar("G-09-53-08", CLASE_53, "L1", "Se me descarga la bateria cuando el auto esta estacionado en la cochera.", "COLOQUIAL", "ESTACIONADO", "descarga_en_cochera", "NO_REPORTA", "", "SI", "NO", "", "L1 descarga estacionado en cochera")
    agregar("G-09-53-09", CLASE_53, "L1", "De noche algo se queda prendido y en la manana no da ni un giro de arranque.", "COLOQUIAL", "REPOSO_NOCTURNO", "algo_prendido_de_noche, sin_giro_manana", "NO_REPORTA", "", "SI", "NO", "", "L1 algo encendido de noche")
    agregar("G-09-53-10", CLASE_53, "L1", "Bateria amanece descargada aunque de dia funciona normal.", "COLOQUIAL", "REPOSO_NOCTURNO", "amanece_descargada, dia_funciona_normal", "NO_REPORTA", "", "SI", "NO", "", "L1 contraste diario vs noche")

    # L2 (15 casos)
    agregar("G-09-53-11", CLASE_53, "L2", "El vehiculo funciona impecable todo el dia en ruta, pero al quedar estacionado en la noche por mas de 8 horas, a la manana siguiente la bateria esta en 10.5V y no enciende.", "COLOQUIAL", "REPOSO_NOCTURNO", "descarga_8_horas_noche, bateria_10_5v, dia_impecable", "descarga_en_marcha", "", "NO", "SI", CLASE_47, "L2 descarga nocturna vs descarga en marcha")
    agregar("G-09-53-12", CLASE_53, "L2", "La bateria tiene solo tres semanas de comprada y fue probada con densimetro al 100%, pero tras dejar el auto parado de viernes a lunes amanece completamente descargada.", "TECNICO", "FIN_DE_SEMANA", "bateria_nueva_probada_100, descarga_viernes_a_lunes", "bateria_defectuosa_fabrica", "", "NO", "SI", CLASE_48, "L2 bateria verificada 100% vs bateria danada")
    agregar("G-09-53-13", CLASE_53, "L2", "Al apagar el motor y cerrar con llave, se nota que la luz interna de la guantera o maletero queda encendida por interruptor descalibrado, drenando la bateria en reposo.", "COLOQUIAL", "REPOSO_NOCTURNO", "luz_maletero_o_guantera_encendida, drenado_en_reposo", "fallo_alternador", "", "NO", "NO", "", "L2 luz de maletero/guantera encendida")
    agregar("G-09-53-14", CLASE_53, "L2", "Se instala radio multimedia aftermarket; durante el dia el alternador mantiene 14.2V de carga en marcha, pero tras apagar el auto la pantalla no entra en modo sleep y vacia la carga en 12 horas.", "TECNICO", "REPOSO_NOCTURNO", "radio_aftermarket_sin_sleep, vaciado_12_horas, alternador_14_2v_ok", "fallo_carga_alternador", "", "NO", "SI", CLASE_47, "L2 radio aftermarket no duerme vs alternador")
    agregar("G-09-53-15", CLASE_53, "L2", "Si desconecto el borne negativo durante la noche, al dia siguiente lo conecto y arranca al primer toque con 12.6V, demostrando que la perdida ocurre por consumo del circuito con el auto apagado.", "TECNICO", "PRUEBA_DESCONEXION", "borne_desconectado_mantiene_carga_12_6v, fuga_circuito_vehiculo", "autodescarga_bateria", "", "NO", "SI", CLASE_48, "L2 prueba borne desconectado vs autodescarga")
    agregar("G-09-53-16", CLASE_53, "L2", "El cierre centralizado de la puerta del copiloto hace un chasquido ciclico cada 20 segundos con el vehiculo cerrado, impidiendo que los modulos de carroceria pasen a modo reposo.", "TECNICO", "VEHICULO_BLOQUEADO", "chasquido_ciclico_cierre, modulos_no_duermen, consumo_permanente", "falla_mecanica_chapa", "", "NO", "SI", CLASE_55, "L2 actuador ciclico despierta red vs cierre")
    agregar("G-09-53-17", CLASE_53, "L2", "Tras apagar el motor y esperar 30 minutos a que duerma la red CAN, se conecta multimetro y se observa un consumo sostenido de 450 miliamperios con todas las luces apagadas.", "TECNICO", "REPOSO_RED_CAN", "consumo_450ma_reposo, can_dormida, luces_apagadas", "consumo_normal_menos_35ma", "", "NO", "NO", "", "L2 medicion 450mA en reposo")
    agregar("G-09-53-18", CLASE_53, "L2", "El alternador carga perfectamente a 14.3V con luces y aire acondicionado encendidos; no hay problema de carga en marcha, la falla es exclusivamente descarga nocturna en estacionamiento.", "TECNICO", "COMPARACION_OPERACIONAL", "alternador_14_3v_carga_ok, descarga_exclusiva_nocturna", "falla_regulador_alternador", "", "NO", "SI", CLASE_47, "L2 alternador 14.3V perfecto vs alternador")
    agregar("G-09-53-19", CLASE_53, "L2", "El rele de los faros antiniebla o desempanador trasero queda con sus contactos pegados aun con el interruptor apagado, calentandose levemente en la fusiblera durante la noche.", "TECNICO", "REPOSO_NOCTURNO", "rele_pegado_caliente_fusiblera, consumo_apagado", "cortocircuito_franco", "", "NO", "NO", "", "L2 rele pegado templado en reposo")
    agregar("G-09-53-20", CLASE_53, "L2", "Se cambio bateria pensando que estaba rota, pero la bateria nueva se descargo a cero tras 48 horas de reposo; la bateria anterior estaba en buen estado.", "COLOQUIAL", "ESTACIONADO_48H", "bateria_nueva_descargada_48h, cambio_bateria_inutil", "bateria_danada", "", "NO", "SI", CLASE_48, "L2 cambio erroneo de bateria vs consumo")
    agregar("G-09-53-21", CLASE_53, "L2", "Alarma no original instalada presenta falla en sensor de impacto volumetrico y mantiene activo el consumo de corriente en la linea de bateria constante en reposo.", "TECNICO", "VEHICULO_ESTACIONADO", "alarma_aftermarket_consumo_linea_constante", "fallo_bateria", "", "NO", "NO", "", "L2 consumo alarma aftermarket")
    agregar("G-09-53-22", CLASE_53, "L2", "Con el vehiculo cerrado y bloqueado, el modulo de control de carroceria BCM no reduce su consumo y mantiene la red despierta, agotando la carga cada manana.", "TECNICO", "VEHICULO_BLOQUEADO", "bcm_no_reduce_consumo, red_despierta, vaciado_manana", "bateria_envejece", "", "NO", "NO", "", "L2 BCM mantiene red despierta")
    agregar("G-09-53-23", CLASE_53, "L2", "Diferencia de sintoma clara: en marcha el voltimetro marca 14.1V constantes sin parpadeo de luces, pero tras 10 horas de estacionamiento la bateria cae de 12.6V a 11.2V.", "TECNICO", "ESTACIONADO_10H", "voltimetro_marcha_14_1v_ok, caida_a_11_2v_en_10h", "alternador_defectuoso", "", "NO", "SI", CLASE_47, "L2 contraste voltajes marcha vs 10h reposo")
    agregar("G-09-53-24", CLASE_53, "L2", "El actuador electrico de la cerradura del maletero no reporta el estado cerrado, provocando que la computadora de confort permanezca en vigilia consumiendo energia.", "TECNICO", "VEHICULO_BLOQUEADO", "maletero_no_reporta_cerrado, computadora_vigilia_consumo", "mecanismo_chapa_trabado", "", "NO", "SI", CLASE_55, "L2 microswitch maletero vigilia vs cerradura")
    agregar("G-09-53-25", CLASE_53, "L2", "El auto se utiliza diariamente para reparto sin problema; si queda guardado sabado y domingo, el lunes el motor de arranque no gira por falta de energia en bateria.", "COLOQUIAL", "FIN_DE_SEMANA", "uso_diario_sin_falla, descarga_sabado_domingo, lunes_sin_energia", "arrancador_danado", "", "NO", "SI", CLASE_52, "L2 lunes sin energia vs motor arranque 52")

    # L3 (15 casos)
    agregar("G-09-53-26", CLASE_53, "L3", "Diagnostico de consumo parasito en reposo en taller: medicion con pinza amperimetrica DC de baja corriente en borne negativo tras 45 minutos de cierre y bloqueo con red CAN dormida registra 680 mA continuos (especificacion maxima OEM: 35 mA). Al extraer fusible F24 de 15A correspondiente a sistema de audio infotainment el consumo desciende a 22 mA.", "TECNICO", "TALLER_AMPERIMETRO", "consumo_reposo_680ma, extraccion_fusible_f24_baja_a_22ma, red_can_dormida", "falla_bateria", "", "NO", "NO", "", "L3 pinza DC 680mA fusible F24 baja a 22mA")
    agregar("G-09-53-27", CLASE_53, "L3", "Localizacion de fuga parasita mediante medicion de caida de tension en milivoltios (mV) a traves de fusibles tipo mini: en fusible F12 (10A) se registran 3.8 mV de caida con voltimetro digital en escala de mV DC. Segun tabla de conversion para fusible de 10A, esto equivale a 490 mA de corriente drenandose de forma permanente por modulo de telematica.", "TECNICO", "TALLER_MILIVOLTIOS", "caida_3_8mv_fusible_10a, corriente_calculada_490ma, telematica", "falla_alternador", "", "NO", "NO", "", "L3 caida mV en fusible tabla conversion 490mA")
    agregar("G-09-53-28", CLASE_53, "L3", "Comprobacion de estado de bateria y alternador: probador Midtronics certifica bateria de 12V con 100% de salud (SOH) y 580 CCA reales; alternador entrega 14.35V en ralenti con ondulacion de rizado AC de solo 0.04V. Sin embargo, con llave fuera y reposo de 60 minutos se registra corriente parasita de 820 mA atribuible a rele de calefaccion auxiliar trabado.", "TECNICO", "TALLER_INTEGRAL", "midtronics_100_soh_580cca, alternador_14_35v_0_04v_ripple, fuga_820ma_rele_calefaccion", "bateria_agotada, diodo_alternador_abierto", "", "NO", "SI", CLASE_47, "L3 Midtronics 100% alternador 14.35V fuga 820mA")
    agregar("G-09-53-29", CLASE_53, "L3", "Evaluacion de corriente en reposo: con osciloscopio y pinza amperimetrica acoplada en DC, se evidencia que la red CAN-Bus intenta entrar en sleep mode cada 3 minutos pero se despierta inmediatamente por pulsos espurios del actuador de cerradura de puerta trasera izquierda, manteniendo consumo medio de 520 mA.", "TECNICO", "TALLER_OSCILOSCOPIO", "red_can_despierta_cada_3min, pulsos_actuador_cerradura, consumo_520ma", "falla_mecanica_puerta", "", "NO", "SI", CLASE_55, "L3 CAN despierta por actuador puerta 520mA")
    agregar("G-09-53-30", CLASE_53, "L3", "Procedimiento de rastreo de consumo nocturno segun manual de servicio: vehiculo cerrado con pestillos y capo simulado cerrado. Medicion inicial en serie: 1.1A; a los 25 minutos cae a 750 mA y se estabiliza ahi. Al retirar el rele RLY_ACC el consumo baja bruscamente a 18 mA, confirmando puenteo resistivo interno de 16 Ohmios entre contactos 30 y 87.", "TECNICO", "TALLER_PROCEDIMIENTO", "medicion_serie_750ma_estable, retiro_rele_acc_baja_a_18ma, puenteo_16_ohm", "consumo_normal", "", "NO", "NO", "", "L3 medicion serie 750mA rele ACC baja a 18mA")
    agregar("G-09-53-31", CLASE_53, "L3", "Diagnostico diferencial estricto frente a bateria defectuosa: bateria con tension en reposo de 12.68V tras carga independiente. Instalada en vehiculo sin conectar bornes mantiene 12.65V tras 48 horas. Conectada al automovil con consumo parasito medido de 550 mA cae a 11.40V en 14 horas, confirmando drenaje externo del circuito electrico y no autodescarga de celdas.", "TECNICO", "TALLER_PRUEBA_AISLADA", "bateria_aislada_12_65v_48h, conectada_cae_a_11_40v_14h, fuga_550ma", "autodescarga_quimica", "", "NO", "SI", CLASE_48, "L3 prueba bateria aislada vs conectada 550mA")
    agregar("G-09-53-32", CLASE_53, "L3", "Medicion con multimetro Fluke en serie en polo negativo: corriente parasitaria fija de 380 mA tras 40 minutos de espera. Monitoreo termico con camara infrarroja en fusiblera del habitaculo ubica punto caliente a 36°C en fusible F38 (modulo de control de carroceria BCM), causado por diodo zener de proteccion en fuga interna.", "TECNICO", "TALLER_TERMOGRAFIA", "multimetro_serie_380ma, punto_caliente_36c_fusible_f38_bcm, zener_fuga", "falla_aislamiento_cableado", "", "NO", "NO", "", "L3 termografia fusible F38 36C fuga 380mA")
    agregar("G-09-53-33", CLASE_53, "L3", "Verificacion de circuito de carga y descarga: tension de carga con motor en marcha a 2000 RPM es 14.28V con 35A entregados hacia bateria. Tras apagar motor, apagar luces y bloquear puertas, el consumo residual es de 440 mA sostenidos; desconectando el conector del amplificador de sonido de fabrica el consumo cae a 19 mA conformes a norma.", "TECNICO", "TALLER_COMPROBACION", "carga_14_28v_35a_ok, consumo_residual_440ma, amplificador_desconectado_19ma", "alternador_baja_carga", "", "NO", "SI", CLASE_47, "L3 alternador 14.28V 35A ok amplificador 440mA")
    agregar("G-09-53-34", CLASE_53, "L3", "Prueba de caida de tension en fusibles maxi en vano motor: fusible de 50A de alimentacion a modulo de puerta del conductor muestra 0.6 mV de caida continua. Calculo segun formula de resistencia de fusible arroja corriente parasitaria de 390 mA por microinterruptor de cerradura sulfatado que impide reposo del procesador.", "TECNICO", "TALLER_MILIVOLTIOS", "maxifusible_50a_0_6mv, corriente_calculada_390ma, microinterruptor_sulfatado", "fallo_bateria", "", "NO", "SI", CLASE_55, "L3 maxifusible 50A 0.6mV microinterruptor puerta")
    agregar("G-09-53-35", CLASE_53, "L3", "Protocolo de busqueda de drenaje nocturno: corriente de reposo registrada de 920 mA con todas las cargas desconectadas. Al desconectar alternador (borne B+) la fuga se mantiene en 920 mA (descartando puente rectificador); al desconectar modulo de rastreo GPS satelital no original el consumo desciende a 25 mA.", "TECNICO", "TALLER_DESCONEXION", "corriente_reposo_920ma, descarte_borne_b_alternador, gps_satelital_baja_a_25ma", "diodos_alternador_en_fuga", "", "NO", "SI", CLASE_47, "L3 descarte borne B+ alternador GPS 920mA")
    agregar("G-09-53-36", CLASE_53, "L3", "Inspeccion tecnica en vehiculo de 12V: la bateria amanecia en 10.9V cada dos dias. Se mide corriente en reposo arrojando 610 mA continuos; analisis con punta logica en bus LIN detecta comunicacion continua sin transicion a estado de baja potencia por parte del sensor de lluvia y luz del parabrisas.", "TECNICO", "TALLER_OSCILOSCOPIO", "bateria_10_9v_dos_dias, corriente_reposo_610ma, bus_lin_despierto_sensor_lluvia", "bateria_sulfatada", "", "NO", "SI", CLASE_48, "L3 bus LIN sensor lluvia despierto 610mA")
    agregar("G-09-53-37", CLASE_53, "L3", "Medicion con registrador de datos de corriente (Datalogger) durante 8 horas de estacionamiento: la corriente se mantiene constante entre 430 mA y 470 mA durante toda la madrugada, totalizando un consumo acumulado de 3.6 Ah que deja a la bateria de 45 Ah por debajo de su umbral de arranque en frio.", "TECNICO", "TALLER_DATALOGGER", "datalogger_8h_450ma_constante, consumo_acumulado_3_6ah, umbral_arranque_superado", "falla_motor_arranque", "", "NO", "SI", CLASE_52, "L3 datalogger 8h 450mA acumulado 3.6Ah")
